UNIT_ZH, UNIT_EN = "反向傳播的演算法", "Backprop steps"
TITLE_ZH = "圖型識別 第四章 KP07：反向傳播的演算法（大三）"; TITLE_EN = "Pattern Recognition, Chapter 4, KP07: the backpropagation algorithm (undergraduate)"
NOTE_ZH = "教材程度：大學三年級（undergrad）。依講義 lec05-kp07 以 view-from-text-v3 製作：先規劃頁面，每頁以一張原生資訊圖（HTML 設計後轉成原生節點）為主，名詞在同一頁圖內定義。共 10 頁，所有數字皆由程式計算。"
NOTE_EN = "Level: undergraduate (year 3). Made from the lecture lec05-kp07 with view-from-text-v3: pages were planned first and each page is mainly one native infographic (designed in HTML and converted to native nodes), with the terms defined on the same page. 10 pages; every number is computed by program."
def fig(n, alt_zh, alt_en):
    return lambda: native(f"kp07_p{n}", f"lec05-kp07-p{n}", KP.W, KP.H, JD, alt_en if os.environ.get("KP_LANG") == "en" else alt_zh)
P = []
NXT = {1: ("第一個 epoch 的前向", "the forward pass of the first epoch"), 2: ("第一個 epoch 的反向與更新", "the backward pass and update of the first epoch"), 3: ("J 的下降曲線", "the falling curve of J"), 4: ("學習率的兩難", "the learning-rate dilemma"), 5: ("全 0 起始值", "the all-zero start"), 6: ("區域極小值", "the local minimum"), 7: ("批次與逐筆", "batch versus pattern training"), 8: ("凍結權重", "frozen weights"), 9: ("小練習", "the exercises")}
PREV = {2: ("訓練迴圈", "the training loop"), 3: ("第一個 epoch 的前向", "the forward pass of the first epoch"), 4: ("第一個 epoch 的反向與更新", "the backward pass and update of the first epoch"), 5: ("J 的下降曲線", "the falling curve of J"), 6: ("學習率的兩難", "the learning-rate dilemma"), 7: ("全 0 起始值", "the all-zero start"), 8: ("區域極小值", "the local minimum"), 9: ("批次與逐筆", "batch versus pattern training"), 10: ("凍結權重", "frozen weights")}
def add(n, lab, title, bridge, notes, alt):
    zh, en = notes
    if n in PREV: zh = f"承接上一頁的「{PREV[n][0]}」。" + zh; en = f"Following the previous page on {PREV[n][1]}. " + en
    if n == 10: zh += "到這裡這個單元就結束了；之後請接著讀下一單元。"; en += " That ends this unit; next, move on to the next unit."
    if n in NXT: zh += f"接下來的下一頁是「{NXT[n][0]}」。"; en += f" Next, the next page covers {NXT[n][1]}."
    P.append(dict(lab=lab, title=title, bridge=bridge, notes=(zh, en), layout="freeform", spec=fig(n, *alt)))
add(1, ("訓練迴圈", "Training loop"),
    ("反向傳播訓練重複四個步驟：起始值之後，每個 epoch 前向、反向、更新，直到停止", "Backprop training: start values, then forward, backward and update each epoch until it stops"),
    ("KP06 只走了一筆樣本的一步。真正的訓練要怎麼重複、什麼時候停？", "KP06 took one step for one sample. How does real training repeat, and when does it stop?"),
    ("這是 KP07 的第一頁。先備三件事（KP06）：前向傳遞、誤差訊號 δ，以及連鎖律與反向傳播。實驗設定：XOR 四個點、2–2–1 網路共 9 個權重、代價 J 是四筆二分之一乘目標減輸出的平方的平均，停止條件是 J 小於 0.0002 且四點都在 0.5 的正確一側。四個步驟：① 給每個權重一個小的隨機起始值，只做一次；② 前向並存值；③ 反向算每筆的 δ；④ 更新；重複 ② 到 ④ 直到停止。epoch 是把全部 N 筆資料呈現完一次，本例 N 等於 4。批次訓練是一個 epoch 裡每筆都先算 δ，加總後只更新一次，Δw 等於 η 除以 N 乘以各筆 δ 乘輸入的總和；除以 N 只是改變 η 的尺度。",
     "This is the first page of KP07. Prerequisites (KP06): the forward pass, the error signal delta, and the chain rule with backpropagation. Setup: the four XOR points, a 2-2-1 network with 9 weights, the cost J as the mean over the four samples of one half of the squared difference between target and output, and the stop rule J below 0.0002 with all four points on the correct side of 0.5. The four steps: 1 give every weight a small random start value, once only; 2 forward and store the values; 3 backward to get each sample's delta; 4 update; repeat 2 to 4 until it stops. An epoch presents all N samples once, here N equals 4. Batch training computes delta for every sample in the epoch, adds them up and updates once: delta w equals eta over N times the sum of delta times input; dividing by N only rescales eta."),
    ("Flow chart of the four steps: 1 start values (once), 2 forward, 3 backward, 4 update, repeating 2 to 4; definitions of epoch and batch training with the batch update formula.",) * 2)
add(2, ("前向", "Forward"),
    ("起始權重下四個點的輸出為 0.2578、0.9851、0.9851、0.0043，J = 0.00837", "With the start weights the four outputs are 0.2578, 0.9851, 0.9851, 0.0043 and J = 0.00837"),
    ("反向傳播訓練重複四個步驟：起始值之後，每個 epoch 前向、反向、更新，直到停止。用具體的權重走第一個 epoch，前向先得到什麼？", "Backprop training: start values, then forward, backward and update each epoch until it stops. What does the forward pass of the first epoch give with concrete weights?"),
    ("這一頁用來源互動例的初始權重走第一個 epoch 的前向。偏置、x1、x2 依序：隱藏單元 1 是 (負 2, 5, 5)，隱藏單元 2 是 (負 7, 5, 5)，輸出單元是 (負 2, 8, 負 12)。四個點的隱藏輸出與最終輸出（程式計算）：(0,0) 的 h 是 0.1192 與 0.0009，o 是 0.2578；(0,1) 與 (1,0) 的 h 是 0.9526 與 0.1192，o 是 0.9851；(1,1) 的 h 是 0.9997 與 0.9526，o 是 0.0043。各筆二分之一乘目標減輸出的平方是 0.03324、0.00011、0.00011、0.00001，平均得 J 等於 0.00837。四個點都已在 0.5 的正確一側。",
     "This page runs the forward pass of the first epoch with the initial weights of the source demo. In the order bias, x1, x2: hidden unit 1 is (minus 2, 5, 5), hidden unit 2 is (minus 7, 5, 5) and the output unit is (minus 2, 8, minus 12). The hidden and final outputs of the four points (computed by program): for (0,0) h is 0.1192 and 0.0009 and o is 0.2578; for (0,1) and (1,0) h is 0.9526 and 0.1192 and o is 0.9851; for (1,1) h is 0.9997 and 0.9526 and o is 0.0043. One half of the squared difference is 0.03324, 0.00011, 0.00011 and 0.00001, and the mean gives J equal to 0.00837. All four points are already on the correct side of 0.5."),
    ("2-2-1 network with weights (-2,5,5), (-7,5,5), (-2,8,-12) and a table: outputs 0.2578, 0.9851, 0.9851, 0.0043 for the four XOR points; J = 0.00837.",) * 2)
add(3, ("反向與更新", "Backward and update"),
    ("第一個 epoch：只有 (0, 0) 的 δ 大，九個權重各更新一次，J 從 0.00837 降到 0.00799", "Epoch 1: only (0, 0) has a large δ; nine weights update once and J falls from 0.00837 to 0.00799"),
    ("四個點的輸出為 0.2578、0.9851、0.9851、0.0043，J = 0.00837。反向與更新之後，J 降多少？", "The four outputs are 0.2578, 0.9851, 0.9851, 0.0043 and J = 0.00837. After backward and update, how much does J fall?"),
    ("這一頁做反向與更新。各筆輸出層的 δ 等於 (目標減 o) 乘 o 乘 (1 減 o)（程式計算）：(0,0) 是負 0.0493，(0,1) 與 (1,0) 各約正 0.0002，(1,1) 約負 0.00002。把四筆的 δ 乘輸入加總、除以 4、乘 η 等於 1.5，九個權重各更新一次：輸出偏置負 0.0183、隱藏單元 1 的偏置負 0.0155，其餘都更小。一個 epoch 後 J 從 0.00837 降到 0.00799，只走了一小步。",
     "This page does the backward pass and the update. The output-layer delta of each sample equals (target minus o) times o times (1 minus o) (computed by program): minus 0.0493 for (0,0), about plus 0.0002 for each of (0,1) and (1,0), and about minus 0.00002 for (1,1). Summing delta times input over the four samples, dividing by 4 and multiplying by eta equal to 1.5 updates each of the nine weights once: the output bias by minus 0.0183, the bias of hidden unit 1 by minus 0.0155, and all others by less. After one epoch J falls from 0.00837 to 0.00799, only a small step."),
    ("Output-layer deltas -0.0493, +0.0002, +0.0002, -0.00002 and a 3x3 shaded grid of the nine updates; darkest are the output bias -0.0183 and the hidden-1 bias -0.0155; J falls from 0.00837 to 0.00799.",) * 2)
add(4, ("J 的下降", "Fall of J"),
    ("J 一路緩降，要到第 3707 個 epoch 才低於門檻 0.0002", "J falls slowly and drops below the bar 0.0002 only at epoch 3707"),
    ("第一個 epoch：只有 (0, 0) 的 δ 大，J 從 0.00837 降到 0.00799，只走了一小步。要走多少個 epoch？", "Epoch 1: only (0, 0) has a large δ and J falls from 0.00837 to 0.00799, a small step. How many epochs does it take?"),
    ("這一頁看 J 的下降曲線，兩軸都用對數座標。停止條件：代價 J 小於門檻，或梯度小到幾乎不變；本例取 J 小於 0.0002 且四點全對。η 等於 1.5、來源初始權重、批次訓練：J 在第 1、10、100、1000 個 epoch 是 0.00799、0.00567、0.00175、0.00046，第 3707 個 epoch 才低於門檻；此時四個輸出是 0.029、0.982、0.982、0.010（程式計算）。",
     "This page shows the falling curve of J, with both axes on a log scale. The stop rule: the cost J falls below a bar, or the gradient is so small that nothing changes; here J below 0.0002 with all four points correct. With eta 1.5, the source start weights and batch training, J is 0.00799, 0.00567, 0.00175 and 0.00046 at epochs 1, 10, 100 and 1000, and only at epoch 3707 does it fall below the bar; the four outputs are then 0.029, 0.982, 0.982 and 0.010 (computed by program)."),
    ("Log-log curve of J against epoch from 0.00837 falling through 0.00175 at 100 and 0.00046 at 1000 to below the bar 0.0002 at epoch 3707.",) * 2)
add(5, ("學習率", "Learning rate"),
    ("學習率 η 從 0.1 到 100，epoch 數從 55,607 降到 53；η = 200 就失敗", "As η goes from 0.1 to 100 the epochs fall from 55,607 to 53; at η = 200 training fails"),
    ("J 要到第 3707 個 epoch 才低於門檻 0.0002。學習率可以調大加速嗎？", "J drops below the bar 0.0002 only at epoch 3707. Can a larger learning rate speed it up?"),
    ("這一頁看學習率。來源初始權重、批次訓練，所需 epoch 數隨 η（程式計算）：0.1 是 55,607，0.5 是 11,121，1.5 是 3,707，3 是 1,853，6 是 926，30 是 185，100 是 53，200 失敗。η 等於 200 時 J 前兩步就變大，從 0.00837 到 0.0828 再到 0.25，最後四個輸出都是 1.00，只對 2 點，訓練失敗。來源指出最佳 η 取決於代價在權重空間的形狀：平坦的極小值可以大步走，陡峭狹窄的要小步。常見迷思是越大越好；其實是在某個範圍內越大越快。",
     "This page looks at the learning rate. With the source start weights and batch training, the epochs needed against eta (computed by program) are 55,607 at 0.1, 11,121 at 0.5, 3,707 at 1.5, 1,853 at 3, 926 at 6, 185 at 30, 53 at 100, and failure at 200. At eta 200 J grows in the first two steps, from 0.00837 to 0.0828 and then 0.25, and finally all four outputs are 1.00, only 2 points are right, and training fails. The source says the best eta depends on the shape of the cost in weight space: flat minima allow big steps, steep narrow ones need small steps. The common myth is that larger is better; in fact larger is faster only within some range."),
    ("Log-scale bars of epochs for eta 0.1, 0.5, 1.5, 3, 6, 30, 100: 55607, 11121, 3707, 1853, 926, 185, 53, and failure at 200.",) * 2)
add(6, ("起始值", "Start values"),
    ("起始值全是 0，所有梯度剛好是 0：J = 0.125 一動也不動", "With an all-zero start every gradient is exactly 0: J stays at 0.125 and never moves"),
    ("學習率 η 從 0.1 到 100，epoch 數從 55,607 降到 53，η = 200 就失敗。起始權重要怎麼取？全設成 0 可以嗎？", "As η goes from 0.1 to 100 the epochs fall from 55,607 to 53, and η = 200 fails. How should the start weights be chosen: is all zero fine?"),
    ("這一頁看起始值。初始化是訓練前先給每個權重一個起始值，通常是小的隨機值，來自偽隨機數產生器。若全設成 0：每個輸出都是 0.5，輸出層的 δ 對目標 0 是 (0 減 0.5) 乘 0.25 等於 負 0.125，對目標 1 是 正 0.125，四筆正負抵銷；隱藏層的 δ 乘輸出權重 0 也是 0，所有梯度剛好是 0，J 等於 0.125 一動也不動（程式計算）。另取 20 組小隨機起點，每個權重在正負 0.5 均勻取，η 等於 1.5：全部達到 J 小於 0.0002，用了 10,890 到 23,926 個 epoch。",
     "This page looks at the start values. Initialization gives every weight a starting value before training, usually small and random from a pseudo-random generator. If everything is set to 0, every output is 0.5, the output delta is (0 minus 0.5) times 0.25 equal to minus 0.125 for target 0 and plus 0.125 for target 1, and the four cancel; the hidden delta is multiplied by the output weight 0 and is 0 too, so every gradient is exactly 0 and J equal to 0.125 never moves (computed by program). With 20 small random starts, each weight uniform in plus or minus 0.5, and eta 1.5, all reach J below 0.0002, using 10,890 to 23,926 epochs."),
    ("Curves of J: all-zero start flat at 0.125, source start falling; output delta -0.125 and +0.125 cancel; 20 small random starts all converge in 10,890 to 23,926 epochs.",) * 2)
add(7, ("區域極小值", "Local minimum"),
    ("300 組 ±3 隨機起點中 176 組達標、124 組卡住：起點 A 停在 J = 0.0626", "Of 300 random starts in ±3, 176 reach the bar and 124 do not: start A stalls at J = 0.0626"),
    ("起始值全是 0，所有梯度剛好是 0，J = 0.125 一動也不動。隨機值取大一點，一定走得到終點嗎？", "With an all-zero start every gradient is 0 and J stays at 0.125. If the random values are larger, does training always reach the end?"),
    ("這一頁看區域極小值：附近最低、但不是最低的點，梯度為 0，梯度下降走進去就出不來。實驗：300 組隨機起點，種子 0 到 299，每個權重在正負 3 均勻取，η 等於 3、最多 20,000 個 epoch；結果 176 組達標，124 組沒有（程式計算）。起點 A（種子 0）卡在 J 等於 0.0626，輸出 0.01、0.99、0.5、0.5，梯度長度只有 3.4 乘 10 的負 5 次方；再多跑 6 萬個 epoch，J 仍是 0.0625。起點 B（種子 4）在 8,203 個 epoch 收斂。",
     "This page looks at the local minimum: the lowest point nearby but not the lowest overall, where the gradient is 0 and gradient descent cannot leave. The experiment: 300 random starts, seeds 0 to 299, each weight uniform in plus or minus 3, eta 3 and at most 20,000 epochs; 176 reach the bar and 124 do not (computed by program). Start A (seed 0) stalls at J equal to 0.0626 with outputs 0.01, 0.99, 0.5 and 0.5 and a gradient length of only 3.4 times 10 to the minus 5; after 60,000 more epochs J is still 0.0625. Start B (seed 4) converges in 8,203 epochs."),
    ("Curves of J for start A (stuck at 0.0626) and start B (reaching the bar at epoch 8203); 176 of 300 random starts reach the bar and 124 do not.",) * 2)
add(8, ("批次與逐筆", "Batch vs pattern"),
    ("逐筆訓練 924 個 epoch、批次 η = 6 要 926：逐筆快是步長，且救不了起點 A", "Pattern training takes 924 epochs, batch η = 6 takes 926: speed is step size; start A stays stuck"),
    ("300 組隨機起點中 176 組達標、124 組卡住，起點 A 停在 J = 0.0626。每看一筆就更新，能不能跳出去？", "Of 300 random starts 176 reach the bar and 124 do not; start A stalls at J = 0.0626. Can updating after every sample escape?"),
    ("這一頁比較逐筆與批次。逐筆訓練每看一筆就用那一筆的 δ 更新一次，w 等於 w 加 η 乘 δ 乘上一層的輸出；隨機性大，來源說有機會跳出區域極小值。來源權重、三種做法所需的 epoch（程式計算）：逐筆 η 等於 1.5 是 924，批次 η 等於 1.5 是 3,707，批次 η 等於 6 是 926，總步長相同。逐筆與批次 η 等於 6 幾乎一樣，所以逐筆快主要是步長，不是魔法。卡住的起點 A：逐筆（固定順序或每個 epoch 洗牌）20,000 個 epoch 後仍在 J 約 0.063，本例沒有跳出；「有機會」不是保證。",
     "This page compares pattern and batch training. Pattern training updates after every sample using that sample's delta, w equals w plus eta times delta times the output of the layer below; it is noisy, and the source says it may escape a local minimum. With the source weights, the epochs needed (computed by program) are 924 for pattern eta 1.5, 3,707 for batch eta 1.5 and 926 for batch eta 6, with the same total step length. Pattern mode and batch with eta 6 are nearly equal, so pattern mode is fast mainly because of the step size, not magic. The stuck start A, with pattern training in fixed order or reshuffled each epoch, is still at J about 0.063 after 20,000 epochs and does not escape here; may escape is not a guarantee."),
    ("Bars of epochs: pattern eta 1.5 is 924, batch eta 1.5 is 3707, batch eta 6 is 926; with pattern training start A is still at J about 0.063 after 20000 epochs.",) * 2)
add(9, ("凍結權重", "Frozen weights"),
    ("訓練完成後凍結 9 個權重：每個輸入只要 6 次乘法與 3 次 sigmoid", "Training done: 9 frozen weights; each input needs 6 multiplications and 3 sigmoids"),
    ("逐筆訓練 924 個 epoch、批次 η = 6 要 926，逐筆快是步長，且救不了起點 A。訓練完成後，權重怎麼用？", "Pattern training takes 924 epochs and batch with η = 6 takes 926; pattern mode cannot save start A. After training, how are the weights used?"),
    ("這一頁看凍結權重：訓練完成後權重不再更新，之後分類只做乘加與 sigmoid。本例 9 個權重為隱藏 1 是 (負 2.862, 5.465, 5.465)，隱藏 2 是 (負 7.843, 4.636, 4.636)，輸出是 (負 3.989, 9.089, 負 11.977)；每個輸入要 6 次乘法與 3 次 sigmoid，四個輸出是 0.0292、0.9821、0.9821、0.0103（程式計算）。同一層的單元彼此獨立，所以可以平行，有光學、VLSI 與專用神經計算機的實作（來源）。",
     "This page looks at frozen weights: after training the weights are no longer updated, and classifying needs only multiply-adds and sigmoids. The 9 weights are hidden 1 equal to (minus 2.862, 5.465, 5.465), hidden 2 equal to (minus 7.843, 4.636, 4.636) and the output (minus 3.989, 9.089, minus 11.977); each input needs 6 multiplications and 3 sigmoids, and the four outputs are 0.0292, 0.9821, 0.9821 and 0.0103 (computed by program). Units of the same layer are independent so they can run in parallel; optical, VLSI and dedicated neural-computer implementations exist (source)."),
    ("The 9 frozen weights hidden 1 (-2.862, 5.465, 5.465), hidden 2 (-7.843, 4.636, 4.636), output (-3.989, 9.089, -11.977) and the outputs 0.0292, 0.9821, 0.9821, 0.0103; 6 multiplications and 3 sigmoids per input.",) * 2)
add(10, ("小練習", "Exercises"),
    ("兩題小練習：輸出層 δ = −0.0493；三個輸出權重更新量 −0.0740、−0.0088、−0.0001", "Two exercises: output δ = −0.0493; output-weight updates −0.0740, −0.0088 and −0.0001"),
    ("訓練完成後凍結 9 個權重，每個輸入只要 6 次乘法與 3 次 sigmoid。用起始權重與 (0, 0) 算一步，答案是多少？", "Training done: 9 frozen weights, 6 multiplications and 3 sigmoids per input. What does one step from the start weights with (0, 0) give?"),
    ("兩題小練習。起始權重，逐筆模式只看樣本 (0,0)，目標 0，η 等於 1.5，前向 h1 等於 0.1192、h2 等於 0.0009、o 等於 0.2578。題 1：輸出層 δ 等於 (0 減 0.2578) 乘 0.2578 乘 0.7422 等於 負 0.0493；核對：輸出 0.2578 比目標 0 高，所以 δ 是負的。題 2：Δw 等於 1.5 乘 負 0.0493 乘輸入，偏置 負 0.0740，來自 h1 的權重 負 0.0088，來自 h2 的權重 負 0.0001；核對：三個都是負的，輸出層權重都往下調；隱藏單元 1 的 δ 等於 負 0.0414，偏置 負 0.0622（程式計算）。",
     "Two exercises. With the start weights, pattern mode and only sample (0,0), target 0, eta equal to 1.5, the forward pass gives h1 equal to 0.1192, h2 equal to 0.0009 and o equal to 0.2578. Q1: the output delta equals (0 minus 0.2578) times 0.2578 times 0.7422, which is minus 0.0493; check: the output 0.2578 is above the target 0, so delta is negative. Q2: delta w equals 1.5 times minus 0.0493 times the input: bias minus 0.0740, weight from h1 minus 0.0088, weight from h2 minus 0.0001; check: all three are negative so the output weights move down; hidden unit 1 has delta minus 0.0414 and bias minus 0.0622 (computed by program)."),
    ("Exercise 1: output delta = (0-0.2578)x0.2578x0.7422 = -0.0493. Exercise 2: updates 1.5 x (-0.0493) x input: bias -0.0740, from h1 -0.0088, from h2 -0.0001.",) * 2)
PAGES = P
